22	/**
23	 * 运行监测：末端加臭浓度检测。
24	 *
25	 * <ul>
26	 *   <li>合格区间为目标浓度（20mg/m³）上下 20% 的<b>闭区间</b>，恰在边界判合格；</li>
27	 *   <li>合格即把连续越限计数归零；<b>恰连续 2 次</b>越限触发告警并锁定加注阀
28	 *       （第 1 次仅按比例修正加注速率，不告警），同时生成待双人确认的触发锁阀单；</li>
29	 *   <li>对应业务日期已封存时，本次数据只落迟到事件，不联动、不改阀门状态；</li>
30	 *   <li>全程在幂等事务内执行，阀门状态以行锁串行裁决。</li>
31	 * </ul>
32	 */
33	@Service
34	public class OdorantService {
35	
36	    private static final int BREACH_LIMIT_TO_LOCK = 2;
37	
38	    private final StationRepository stationRepository;
39	    private final ValveStateRepository valveStateRepository;
40	    private final OdorantReadingRepository readingRepository;
41	    private final LateEventRepository lateEventRepository;
42	    private final LockOrderRepository lockOrderRepository;
43	    private final DailyCloseRepository dailyCloseRepository;
44	    private final IdempotencyService idempotencyService;
45	
46	    public OdorantService(StationRepository stationRepository,
47	                          ValveStateRepository valveStateRepository,
48	                          OdorantReadingRepository readingRepository,
49	                          LateEventRepository lateEventRepository,
50	                          LockOrderRepository lockOrderRepository,
51	                          DailyCloseRepository dailyCloseRepository,
52	                          IdempotencyService idempotencyService) {
53	        this.stationRepository = stationRepository;
54	        this.valveStateRepository = valveStateRepository;
55	        this.readingRepository = readingRepository;
56	        this.lateEventRepository = lateEventRepository;
57	        this.lockOrderRepository = lockOrderRepository;
58	        this.dailyCloseRepository = dailyCloseRepository;
59	        this.idempotencyService = idempotencyService;
