3	import org.springframework.http.HttpStatus;
4	import org.springframework.http.ResponseEntity;
5	import org.springframework.web.bind.MethodArgumentNotValidException;
6	import org.springframework.web.bind.annotation.ExceptionHandler;
7	import org.springframework.web.bind.annotation.RestControllerAdvice;
8	
9	import java.time.OffsetDateTime;
10	import java.util.LinkedHashMap;
11	import java.util.Map;
12	
13	/**
14	 * 统一错误响应：409 幂等冲突/任务未受理、404 资源不存在、400 参数非法。
15	 */
16	@RestControllerAdvice
17	public class GlobalExceptionHandler {
18	
19	    @ExceptionHandler(IdempotentConflictException.class)
20	    public ResponseEntity<Map<String, Object>> handleConflict(IdempotentConflictException ex) {
21	        return build(HttpStatus.CONFLICT, ex.getMessage());
22	    }
23	
24	    @ExceptionHandler(TaskNotAcceptedException.class)
25	    public ResponseEntity<Map<String, Object>> handleNotAccepted(TaskNotAcceptedException ex) {
26	        return build(HttpStatus.CONFLICT, ex.getMessage());
27	    }
28	
29	    @ExceptionHandler(ResourceNotFoundException.class)
30	    public ResponseEntity<Map<String, Object>> handleNotFound(ResourceNotFoundException ex) {
31	        return build(HttpStatus.NOT_FOUND, ex.getMessage());
32	    }
33	
34	    @ExceptionHandler(MethodArgumentNotValidException.class)
35	    public ResponseEntity<Map<String, Object>> handleValidation(MethodArgumentNotValidException ex) {
36	        String message = ex.getBindingResult().getFieldErrors().stream()
37	                .map(e -> e.getField() + " " + e.getDefaultMessage())
38	                .findFirst()
39	                .orElse("validation failed");
40	        return build(HttpStatus.BAD_REQUEST, message);
41	    }
42	
43	    @ExceptionHandler(IllegalArgumentException.class)
44	    public ResponseEntity<Map<String, Object>> handleIllegalArgument(IllegalArgumentException ex) {
45	        return build(HttpStatus.BAD_REQUEST, ex.getMessage());
46	    }
47	
48	    private ResponseEntity<Map<String, Object>> build(HttpStatus status, String message) {
49	        Map<String, Object> body = new LinkedHashMap<>();
50	        body.put("timestamp", OffsetDateTime.now().toString());
51	        body.put("status", status.value());
52	        body.put("error", status.getReasonPhrase());
53	        body.put("message", message);
54	        return ResponseEntity.status(status).body(body);
55	    }
56	}
