78	    private PressureDetectResponse doDetect(Station station, PressureDetectRequest request) {
79	        BigDecimal measured = request.pressureMpa();
80	        String grade = grade(station, measured);
81	        LocalDate bizDate = request.detectedAt().toLocalDate();
82	
83	        if (dailyCloseRepository.isSealed(station.id(), bizDate)) {
84	            // 封存终态：迟到压力检测只记事件，不触发联动
85	            lateEventRepository.insert(station.id(), "PRESSURE", request.requestId(),
86	                    request.detectedAt(), request);
87	            return new PressureDetectResponse(grade, false, null,
88	                    measured, measured, null, null, BigDecimal.ZERO, true, false);
89	        }
90	
91	        ValveState state = valveStateRepository.selectForUpdate(station.id());
92	
93	        if ("NORMAL".equals(grade)) {
94	            // 恰等限值或区间内：合格，无联动
95	            readingRepository.insert(station.id(), request.requestId(), request.detectedAt(),
96	                    measured, grade, null);
97	            return new PressureDetectResponse(grade, false, null,
98	                    measured, measured,
99	                    state.currentInjectionRateMgM3(), state.currentInjectionRateMgM3(),
100	                    BigDecimal.ZERO, false, false);
101	        }
102	
103	        if (taskLockRepository.existsAtSameInstant(station.id(), request.detectedAt())) {
104	            throw new TaskNotAcceptedException(
105	                    "linkage task already running for station at detectedAt=" + request.detectedAt());
106	        }
107	
108	        Long taskId;
109	        try {
110	            taskId = linkageTaskRepository.insertAccepted(station.id(), request.requestId(),
111	                    request.detectedAt(), measured, state.currentInjectionRateMgM3(),
112	                    request.gasFlowM3());
113	        } catch (DuplicateKeyException concurrent) {
114	            // 同刻并发：唯一约束裁决，仅首个请求受理
115	            throw new TaskNotAcceptedException(
116	                    "linkage task already running for station at detectedAt=" + request.detectedAt());
117	        }
118	
119	        BigDecimal targetPressure = station.pressureTargetMpa();
120	        BigDecimal rateBefore = state.currentInjectionRateMgM3();
121	        BigDecimal rateAfter;
122	        BigDecimal dose;
123	        if (state.injectionLocked()) {
124	            // 加注阀锁定中：加注指令以“维持、零加注量”下发，调压仍执行
125	            rateAfter = rateBefore;
126	            dose = BigDecimal.ZERO.setScale(3, RoundingMode.HALF_UP);
127	        } else {
128	            // 比例投加：联动后速率折算浓度回归目标浓度，本次加注量 = 流量 × 目标浓度
129	            rateAfter = station.targetConcentrationMgM3();
