136	        adjustmentIssueRepository.insert(taskId, station.id(), "PRESSURE", measured, targetPressure);
137	        adjustmentIssueRepository.insert(taskId, station.id(), "INJECTION", rateBefore, rateAfter);
138	        valveStateRepository.updateInjectionAndPressure(station.id(), rateAfter, targetPressure);
139	        linkageTaskRepository.complete(taskId, targetPressure, rateAfter, dose);
140	        readingRepository.insert(station.id(), request.requestId(), request.detectedAt(),
141	                measured, grade, taskId);
142	
143	        return new PressureDetectResponse(grade, true, taskId,
144	                measured, targetPressure, rateBefore, rateAfter, dose, false, false);
