45	     * 不加锁读取，用于重放后返回当前阀门态以外的只读场景。
46	     */
47	    public ValveState find(Long stationId) {
48	        return jdbc.query("""
49	                        SELECT station_id, injection_locked, alarm_active, breach_count,
50	                               current_injection_rate_mg_m3, current_pressure_mpa
51	                        FROM valve_state WHERE station_id = ?
52	                        """,
