63	    public void updateState(Long stationId, boolean locked, boolean alarm, int breachCount,
64	                            BigDecimal injectionRateMgM3, BigDecimal pressureMpa) {
65	        jdbc.update("""
66	                        UPDATE valve_state
67	                        SET injection_locked = ?, alarm_active = ?, breach_count = ?,
68	                            current_injection_rate_mg_m3 = ?, current_pressure_mpa = ?,
69	                            updated_at = CURRENT_TIMESTAMP
70	                        WHERE station_id = ?
71	                        """,
72	                locked, alarm, breachCount, injectionRateMgM3, pressureMpa, stationId);
73	    }
